function BarcodeSvg({value}:{value:string}){
 const ref=useRef<SVGSVGElement|null>(null);
 useEffect(()=>{if(ref.current&&value)JsBarcode(ref.current,value,{format:"CODE128",displayValue:true,fontSize:12,height:42,margin:4})},[value]);
 return <svg ref={ref} aria-label={`Barcode ${value}`}/>;
}

