 async function signIn(e:FormEvent){e.preventDefault();setAuthError("");const {error}=await supabase.auth.signInWithPassword({email,password});if(error)setAuthError(error.message)}
 async function loadBranches(){const {data,error}=await supabase.from("branches").select("*").eq("active",true).order("name");let list:Branch[]=[];if(error){try{list=JSON.parse(localStorage.getItem("retailflow-branches")||"[]") as Branch[]}catch{}if(!list.length)setDataError(error.message)}else{list=(data??[]) as Branch[];localStorage.setItem("retailflow-branches",JSON.stringify(list))}if(list.length){setBranches(list);setCurrentBranch(current=>list.find(b=>b.id===current?.id)??list[0]??null)}}
 async function loadProducts(){if(!currentBranch)return;setLoading(true);setDataError("");const {data,error}=await supabase.from("products").select("id,name,sku,barcode,cost_price,active,categories(name),branch_products!inner(selling_price,quantity_on_hand,reorder_level,active,branch_id)").eq("branch_products.branch_id",currentBranch.id).order("name");if(error){const cached=readCachedCatalogue<Product>(currentBranch.id);if(cached.length){setProducts(cached);setDataError("Offline catalogue loaded. Stock levels reflect the last successful connection.")}else setDataError(error.message)}else{const mapped=((data??[]) as unknown as ProductRow[]).map((p,i)=>{const bp=p.branch_products[0];return{id:p.id,name:p.name,sku:p.sku,barcode:p.barcode??"",price:Number(bp.selling_price),cost:Number(p.cost_price),stock:Number(bp.quantity_on_hand),reorder:Number(bp.reorder_level),active:p.active&&bp.active,category:p.categories?.name??"Uncategorised",color:colors[i%colors.length]}});setProducts(mapped);cacheCatalogue(currentBranch.id,mapped)}setLoading(false)}
 async function loadMovements(){if(!currentBranch)return;const {data,error}=await supabase.from("inventory_movement_history").select("*").eq("branch_id",currentBranch.id).order("created_at",{ascending:false}).limit(25);if(!error)setMovements((data??[]) as Movement[])}
 async function loadProfile(){if(!session)return;const {data,error}=await supabase.from("profiles").select("*").eq("id",session.user.id).single();if(error){try{const cached=JSON.parse(localStorage.getItem(`retailflow-profile:${session.user.id}`)||"null") as StaffProfile|null;if(cached)setProfile(cached);else setDataError(error.message)}catch{setDataError(error.message)}}else{const current=data as StaffProfile;setProfile(current);localStorage.setItem(`retailflow-profile:${session.user.id}`,JSON.stringify(current));if(!current.active){await supabase.auth.signOut();setAuthError("Your staff account is inactive.")}}}
 async function openStaff(){setView("staff");const [staffResult,assignmentResult]=await Promise.all([supabase.from("profiles").select("*").order("created_at"),supabase.from("staff_branch_assignments").select("staff_id,branch_id")]);if(staffResult.error)setStaffMessage(staffResult.error.message);else setStaff((staffResult.data??[]) as StaffProfile[]);if(!assignmentResult.error)setAssignments(assignmentResult.data??[])}
 async function updateStaff(id:string,changes:Partial<Pick<StaffProfile,"role"|"active">>){setStaffMessage("");const {error}=await supabase.from("profiles").update({...changes,updated_at:new Date().toISOString()}).eq("id",id);if(error)setStaffMessage(error.message);else{setStaffMessage("Staff access updated successfully.");await openStaff()}}
 async function toggleAssignment(staffId:string,branchId:string){const exists=assignments.some(a=>a.staff_id===staffId&&a.branch_id===branchId);const result=exists?await supabase.from("staff_branch_assignments").delete().eq("staff_id",staffId).eq("branch_id",branchId):await supabase.from("staff_branch_assignments").insert({staff_id:staffId,branch_id:branchId});if(result.error)setStaffMessage(result.error.message);else{setStaffMessage("Branch assignment updated.");await openStaff()}}
 async function openInventory(){setView("inventory");await Promise.all([loadProducts(),loadMovements()])}
 async function loadDashboard(branch=dashboardBranch,from=dashboardFrom,to=dashboardTo){const selected=branch||(profile?.role==="admin"?"all":currentBranch?.id??"");if(!selected)return;setLoading(true);setDashboardMessage("");const [salesResult,expenseResult]=await Promise.all([supabase.rpc("get_sales_dashboard",{p_branch_id:selected==="all"?null:selected,p_from:from,p_to:to}),supabase.rpc("get_expense_summary",{p_branch_id:selected==="all"?null:selected,p_from:from,p_to:to})]);if(salesResult.error)setDashboardMessage(salesResult.error.message);else if(expenseResult.error)setDashboardMessage(expenseResult.error.message);else setDashboard({...salesResult.data,...expenseResult.data} as DashboardData);setLoading(false)}
