 async function exportSalesCsv(){const branch=dashboardBranch||(profile?.role==="admin"?"all":currentBranch?.id??"");let request=supabase.from("sales").select("receipt_number,created_at,total,subtotal,vat_amount,payment_method,branches(code,name)").gte("created_at",`${dashboardFrom}T00:00:00`).lt("created_at",`${dashboardTo}T23:59:59.999`).order("created_at");if(branch!=="all")request=request.eq("branch_id",branch);const {data,error}=await request;if(error){setDashboardMessage(error.message);return}const quote=(value:unknown)=>`"${String(value??"").replaceAll('"','""')}"`;const rows=(data??[]).map((sale:any)=>[sale.receipt_number,sale.created_at,sale.branches?.code,sale.branches?.name,sale.payment_method,sale.subtotal,sale.vat_amount,sale.total].map(quote).join(","));const csv=["Receipt,Date,Branch Code,Branch,Payment,Subtotal,VAT,Total",...rows].join("\n"),url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"})),link=document.createElement("a");link.href=url;link.download=`retail-sales-${dashboardFrom}-to-${dashboardTo}.csv`;link.click();URL.revokeObjectURL(url)}
 async function loadSalesHistory(){if(!currentBranch)return;setLoading(true);setSalesMessage("");const {data,error}=await supabase.from("sales").select("id,receipt_number,created_at,total,payment_method,branches(code,name)").eq("branch_id",currentBranch.id).order("created_at",{ascending:false}).limit(100);if(error)setSalesMessage(error.message);else setSalesHistory((data??[]) as unknown as SaleHistory[]);setLoading(false)}
