 async function findSaleForReturn(e:FormEvent){e.preventDefault();if(!currentBranch||!returnSearch.trim())return;setLoading(true);setReturnMessage("");const number=Number(returnSearch.replace(/\D/g,""));const {data,error}=await supabase.from("sales").select("id").eq("branch_id",currentBranch.id).eq("receipt_number",number).maybeSingle();if(error)setReturnMessage(error.message);else if(!data)setReturnMessage("Receipt not found at the current branch or you do not have access.");else await startReturn(data.id);setLoading(false)}
 async function startReturn(saleId:string){setLoading(true);setReturnMessage("");const {data,error}=await supabase.rpc("get_sale_receipt",{p_sale_id:saleId});if(error)setReturnMessage(error.message);else{const sale=data as Receipt;setReturnSale(sale);setReturnQty({});setReturnDisposition(Object.fromEntries(sale.items.filter(i=>i.sale_item_id).map(i=>[i.sale_item_id!,"restock"])));setReturnOutcome("refund");setRefundMethod("original");setReturnReason("defective");setReturnNotes("")}setLoading(false)}
 async function submitReturn(e:FormEvent){e.preventDefault();if(!returnSale)return;const items=returnSale.items.filter(i=>i.sale_item_id).map(i=>({sale_item_id:i.sale_item_id,quantity:Number(returnQty[i.sale_item_id!]||0),disposition:returnDisposition[i.sale_item_id!]||"restock"})).filter(i=>i.quantity>0);if(!items.length){setReturnMessage("Select at least one item and quantity to return.");return}setLoading(true);setReturnMessage("");const {error}=await supabase.rpc("create_return_request",{p_sale_id:returnSale.id,p_items:items,p_outcome:returnOutcome,p_refund_method:returnOutcome==="refund"?refundMethod:null,p_reason:returnReason,p_notes:returnNotes.trim()||null});if(error)setReturnMessage(error.message);else{setReturnMessage("Return request submitted for administrator approval.");setReturnSale(null);setReturnQty({});await loadReturns()}setLoading(false)}
 async function decideReturn(id:string,approve:boolean){const notes=window.prompt(approve?"Optional approval notes:":"Reason for rejection:")??"";setLoading(true);setReturnMessage("");const {error}=await supabase.rpc("decide_return",{p_return_id:id,p_approve:approve,p_decision_notes:notes.trim()||null});if(error)setReturnMessage(error.message);else{setReturnMessage(approve?"Return approved and inventory updated.":"Return request rejected.");await Promise.all([loadReturns(),loadProducts(),loadMovements()])}setLoading(false)}
