 async function loadActiveShift(){if(!currentBranch||!session)return;const key=`retailflow-shift:${session.user.id}:${currentBranch.id}`;const {data,error}=await supabase.from("cash_shifts").select("*").eq("branch_id",currentBranch.id).eq("cashier_id",session.user.id).eq("status","open").maybeSingle();if(!error){const shift=(data as CashShift|null)??null;setShiftConfigured(true);setActiveShift(shift);if(shift)localStorage.setItem(key,JSON.stringify(shift));else localStorage.removeItem(key)}else{try{const cached=JSON.parse(localStorage.getItem(key)||"null") as CashShift|null;setShiftConfigured(true);setActiveShift(cached)}catch{setShiftConfigured(false)}}}
 async function loadShifts(){if(!currentBranch)return;setLoading(true);setShiftMessage("");const {data,error}=await supabase.from("cash_shifts").select("*").eq("branch_id",currentBranch.id).order("opened_at",{ascending:false}).limit(100);if(error)setShiftMessage(error.message);else setShifts((data??[]) as CashShift[]);setLoading(false)}
